INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6571, 897236, 'tt13273264', NULL, 'The Diabetes Solution', 'The Diabetes Solution', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/mCIeZalqTbyfA1v7cucRyy1FTYf.jpg', 'https://image.tmdb.org/t/p/original/whY5E7vjDny9mmvmZNQhbgEWC7r.jpg', 'The diabetes community has been filled with deception for the past 50 years. The typical guidelines for managing diabetes have ultimately caused suffering for millions of people with the disease. Follow a group of families and doctors as they present a solution to managing diabetes that could spare many patients from devastating complications in this seminal documentary about diabetes.', NULL, NULL, 0.107, 10.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
