INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6582, 2022, 'tt0280590', NULL, 'Mr. Deeds', 'Mr. Deeds', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/7gGk3pkpRsNlJ4PrJgEfgY9PG43.jpg', 'https://image.tmdb.org/t/p/original/7P3VyWQTnZOYIQnk5seM0YQ9ucg.jpg', 'When Longfellow Deeds, a small-town pizzeria owner and poet, inherits $40 billion from his deceased uncle, he quickly begins rolling in a different kind of dough. Moving to the big city, Deeds finds himself besieged by opportunists all gunning for their piece of the pie. Babe, a television tabloid reporter, poses as an innocent small-town girl to do an exposé on Deeds.', NULL, NULL, 10.4765, 5.923, 0, 1.03, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
