INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6585, 38448, 'tt1235796', NULL, 'Ondine', 'Ondine', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/rQSQisWjIjXnGGenrpjG1GlQcRf.jpg', 'https://image.tmdb.org/t/p/original/myYFabjrPz1Gbt3bB3GnEo6OlSN.jpg', 'On the coast of Cork, Syracuse is a divorced fisherman who has stopped drinking. His precocious daughter Annie has failing kidneys. One day, he finds a nearly-drowned young woman in his net; she calls herself Ondine and wants no one to see her. He puts her up in an isolated cottage that was his mother''s. Annie discovers Ondine''s presence and believes she is a selkie, a seal that turns human while on land. Syracuse is afraid to hope again.', NULL, NULL, 1.3302, 6.389, 0, 1.11, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6586, 10818, 'tt0869977', NULL, 'Water Lilies', 'Naissance des pieuvres', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/oNrs9disgGDtOORToDt5dIqYFBi.jpg', 'https://image.tmdb.org/t/p/original/zZRbCsecON0xIiJjbMvQvuDCsCY.jpg', 'Set during a sultry summer in a French suburb, Marie is desperate to join the local pool''s synchronized swimming team, but is her interest solely for the sake of sport or for a chance to get close to Floriane, the bad girl of the team? Sciamma, and the two leads, capture the uncertainty of teenage sexuality with a sympathetic eye in this delicate drama of the angst of coming-of-age.', NULL, NULL, 2.864, 6.5, 0, 2.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
