INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6588, 126934, 'tt0282123', NULL, 'A Ring of Endless Light', 'A Ring of Endless Light', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/w7gK8wahIPtg2MAtc28FCKjrt2m.jpg', 'https://image.tmdb.org/t/p/original/fTaB3mH63qBb2sgYlvGfVLRBt7e.jpg', 'When 15-year-old Vicky Austin, her sister Suzy and little brother Rob visit their grandfather on Seven Bay Island, Vicky faces several unexpected challenges. Her beloved grandfather, retired Reverend Eaton, seems to be seriously ill, but tries to pretend that nothing is wrong. Vicky met the rich but emotionally troubled Zachary Gray the previous summer, and he reappears to renew the acquaintance. Another boy, 17-year-old Adam Eddington, recruits Vicky to help him with a research project, working with a dolphin called Basil. Vicky discovers she can communicate telepathically with the dolphin and his mate - and possibly with Adam as well', NULL, NULL, 1.2289, 6.577, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
