INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6628, 74180, 'tt0830199', NULL, 'Romeo & Juliet: Sealed with a Kiss', 'Romeo & Juliet: Sealed with a Kiss', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/lTaX3wyKR1nKxhVEavUYDPgLa2S.jpg', 'https://image.tmdb.org/t/p/original/cCgpifVqv8wpgWKASIcxmYq2o9O.jpg', 'A fully animated feature fantasy about two star crossed seals from warring families that fall in love against their parents'' wishes. When Juliet''s father gives her hand in marriage to the monstrous elephant seal Prince, Juliet must fake her death in order to be reunited with Romeo. But the plan goes afoul and it''s a desperate race to the end. With the help of their friends Friar Lawrence and Kissy, the kissing fish, the day is saved and the young lovers are reunited. Romeo & Juliet: Sealed With a Kiss is the ageless tale of love and prejudice set in an undersea world. A film that can be enjoyed by the whole family.', NULL, NULL, 0.7944, 6.6, 0, 11.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
