INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6632, 46332, 'tt1588337', NULL, 'Of Gods and Men', 'Des hommes et des dieux', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/fgrC0w62MCc7Fn77l5RVY0WKv0t.jpg', 'https://image.tmdb.org/t/p/original/5dZC7725ogu9drxXLHoNhWIJsgo.jpg', 'A group of Trappist monks reside in the monastery of Tibhirine in Algeria, where they live in harmony with the largely Muslim population. When a bloody conflict between Algeria''s army and Muslim Jihadi insurgents disrupts the peace, they are forced to consider fleeing the monastery and deserting the villagers they have ministered to. In the face of deadly violence, the monks wrestle with their faith and their convictions.', NULL, NULL, 1.5371, 6.665, 0, 2.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6633, 11225, 'tt0478160', NULL, 'Into Great Silence', 'Die große Stille', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/ctqLEwsIRYIPBGAJaDm4UxnTqpO.jpg', 'https://image.tmdb.org/t/p/original/bDEdXeD4fVyYcvMMG9kDdDs5TGZ.jpg', 'An intimate portrayal of the everyday lives of Carthusian monks of the Grande Chartreuse, high in the French Alps (Chartreuse Mountains). The idea for the film was proposed to the monks in 1984, but the Carthusians said they wanted time to think about it. The Carthusians finally contacted Gröning 16 years later to say they were now willing to permit Gröning to shoot the movie, if he was still interested.', NULL, NULL, 0.948, 6.9, 0, 3.0166666666666666e+00, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6634, 56518, 'tt0042477', NULL, 'The Flowers of St. Francis', 'Francesco, giullare di Dio', 'movie', 1950, 'https://image.tmdb.org/t/p/w500/4db6zjmJK4D5gEzQ0V5JTkRo0X5.jpg', 'https://image.tmdb.org/t/p/original/nkDRQOvrJSkVEo0LSY7RQpCTqSS.jpg', 'In a series of simple and joyous vignettes, director Roberto Rossellini and co-writer Federico Fellini lovingly convey the universal teachings of the People’s Saint: humility, compassion, faith, and sacrifice. Gorgeously photographed to evoke the medieval paintings of Saint Francis’s time, and cast with monks from the Nocera Inferiore Monastery, The Flowers of St. Francis is a timeless and moving portrait of the search for spiritual enlightenment.', NULL, NULL, 0.8425, 7.1, 0, 3.0166666666666666e+00, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6635, 515126, NULL, NULL, 'Trappist', 'Trappist', 'movie', NULL, NULL, NULL, 'This documentary presents the reality of a monk''s life as it is lived at Mepkin Abbey, a Trappist monastery in South Carolina. Combines startling and beautiful images of the past to explore how a monk fits into our modern world.', NULL, NULL, 0.0143, 0.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
