INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6638, 2587, 'tt0069824', NULL, 'Brother Sun, Sister Moon', 'Fratello sole, sorella luna', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/hbe9jnRQKyxtLr2krJR6RBRwzae.jpg', 'https://image.tmdb.org/t/p/original/s3h57HUNewjGiX2kCXaTzg5DAXr.jpg', 'In his delirium from his return from war, Francesco Bernardone goes back in his memories to the days when he lived for parties and carnal pleasures. He slowly recovers, but after the illness he is no longer the Francesco that everybody knew. Instead of spending hours in taverns, he meditates on the beauty of God''s creatures, soon renouncing his riches and his family with plans to rebuild an abandoned church and his life.', NULL, NULL, 2.018, 7.043, 0, 2.025, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
