INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6647, 776503, 'tt10366460', NULL, 'CODA', 'CODA', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', 'https://image.tmdb.org/t/p/original/v85FlkbMYKa5du1glm0YfYNsL2n.jpg', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family''s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.', NULL, NULL, 10.9733, 7.886, 0, 2.13, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6648, 13370, 'tt0310281', NULL, 'A Mighty Wind', 'A Mighty Wind', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/5wUYwAD75BxtJ0Mp4da6XzHIFex.jpg', 'https://image.tmdb.org/t/p/original/4dZnJLpTzy6FKtrZmoViw3yh0CO.jpg', 'Three eclectic, never-quite-famous folk bands come together for the first time in decades following the death of their manager to put on an reunion concert in his honor, at the request of his son.', NULL, NULL, 1.6404, 6.783, 0, 1.23, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6649, 8545, 'tt0147004', NULL, 'Little Voice', 'Little Voice', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/7VxdMxSa3BEAvGl5nLvsgpBwrZH.jpg', 'https://image.tmdb.org/t/p/original/lwluU3TYXBL4AllSxhgqRlhGEIY.jpg', 'After the death of her father, Little Voice or LV becomes a virtual recluse, never going out and hardly ever saying a word. She just sits in her bedroom listening to her father''s collection of old records of Shirley Bassey, Marilyn Monroe and various other famous female singers. But at night time, LV sings, imitating these great singers with surprising accuracy. One night she is overheard by one of her mother''s boyfriends, who happens to be a talent agent. He manages to convince her that her talent is special and arranges for her to perform at the local night club, but several problems arise.', NULL, NULL, 1.6401, 6.462, 0, 1.23, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6650, 5123, 'tt0426931', NULL, 'August Rush', 'August Rush', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/oA6ZeICPINiS6YtD5WZeBaGVmuT.jpg', 'https://image.tmdb.org/t/p/original/i3pONuqGZSR3UYOOdBeU2CiQnxj.jpg', 'Evan, a musically gifted orphan, runs away from his orphanage and searches New York City for his birth parents. On his journey, he''s taken under the wing of the Wizard, a homeless man who lives in an abandoned theater. After discovering his talent, the Wizard gives Evan the name "August Rush" and devises a plan to profit from his talent. Little does Evan know that his parents, Lyla and Louis, are searching for him too.', NULL, NULL, 5.8695, 7.422, 0, 2.025, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6651, 354912, 'tt2380307', NULL, 'Coco', 'Coco', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', 'https://image.tmdb.org/t/p/original/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', NULL, NULL, 33.0417, 8.198, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6652, 460048, 'tt7220754', NULL, 'Heavy Trip', 'Hevi reissu', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/owdppgwOYuuXAXHHY7YvvS0rOJs.jpg', 'https://image.tmdb.org/t/p/original/paGzFsaSKhzRtYLL7X2MYkQn1iM.jpg', 'Turo is stuck in a small village and the best thing in his life is being the lead vocalist for the amateur metal band Impaled Rektum. He and his bandmates have practiced for 12 years without playing a single gig. The guys get a surprise visitor from Norway -- the promoter for a huge heavy metal music festival -- and decide it''s now or never. They steal a van, a corpse, and even a new drummer to make their dreams a reality.', NULL, NULL, 1.8472, 6.869, 0, 1.05, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6653, 716808, 'tt28772978', NULL, 'Heavier Trip', 'Hevimpi reissu', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/fSCxOGXm7mfEU6Y5VEAufnDZPOx.jpg', 'https://image.tmdb.org/t/p/original/cywr26aku0SRTvn1ks6HRoF4SGZ.jpg', 'The world''s hardest - and weirdest - heavy metal band Impaled Rektum is serving their sentence in Norway''s nicest prison. They receive word that guitarist Lotvonen''s parents'' reindeer herding farm is about to come under the hammer. It will take a big gig and big money to save the farm. A breakout ensues and a trip to the world''s biggest heavy festival, Wacken in northern Germany begins. The higher the target, the bigger the obstacles. This is what the boys will experience on their epic journey to the main stage of Wacken - every metalhead''s heaven.', NULL, NULL, 0.8979, 6.621, 0, 1.05, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
