INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6686, 10161, 'tt0097937', NULL, 'My Left Foot: The Story of Christy Brown', 'My Left Foot: The Story of Christy Brown', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/GRAAl0bMQFoFIjV3aunc5jsM5u.jpg', 'https://image.tmdb.org/t/p/original/zjKg04EquTcnVZUfjHboXnXzjcF.jpg', 'No one expects much from Christy Brown, a boy with cerebral palsy born into a working-class Irish family. Though Christy is a spastic quadriplegic and essentially paralyzed, a miraculous event occurs when, at the age of 5, he demonstrates control of his left foot by using chalk to scrawl a word on the floor. With the help of his steely mother — and no shortage of grit and determination — Christy overcomes his infirmity to become a painter, poet and author.', NULL, NULL, 3.8441, 7.531, 0, 2.015, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6687, 11005, 'tt0099077', NULL, 'Awakenings', 'Awakenings', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/9gztZXuHLG6AJ0fgqGd7Q43cWRI.jpg', 'https://image.tmdb.org/t/p/original/tRKTlMoTsAhYpuq19V8Wk3RFY4O.jpg', 'Dr. Malcolm Sayer, a shy research physician, uses an experimental drug to "awaken" the catatonic victims of a rare disease. Leonard is the first patient to receive the controversial treatment. His awakening, filled with awe and enthusiasm, proves a rebirth for Sayer too, as the exuberant patient reveals life''s simple but unutterably sweet pleasures to the introverted doctor.', NULL, NULL, 7.3607, 7.787, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6688, 5156, 'tt0040522', NULL, 'Bicycle Thieves', 'Ladri di biciclette', 'movie', 1948, 'https://image.tmdb.org/t/p/w500/iPdVqIpmR3bRvOQJPrn4pr2KR3q.jpg', 'https://image.tmdb.org/t/p/original/nd6ItWuWGmTKhHXuxVC8kp86CmQ.jpg', 'Unemployed Antonio is elated when he finally finds work hanging posters around war-torn Rome. However on his first day, his bicycle—essential to his work—gets stolen. His job is doomed unless he can find the thief. With the help of his son, Antonio combs the city, becoming desperate for justice.', NULL, NULL, 4.9204, 8.168, 0, 1.03, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6689, 213938, 'tt0088992', NULL, 'The Runner', 'دونده', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/4X2Lle2CWxGCKcoYyMgqT2x43rR.jpg', 'https://image.tmdb.org/t/p/original/fUDpdaHbMn27JOW9B6oQK50sXt4.jpg', 'A young orphan named Amiro lives alone in an abandoned tanker in the Iranian port city of Abadan. He survives by shining shoes, selling water, and collecting deposit bottles. Although he sometimes finds himself at odds with both adults and competing older kids, he finds solace in dreams about departing cargo ships and airplanes—and by running.', NULL, NULL, 0.3955, 7.244, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
