INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6691, 477652, 'tt6298600', NULL, 'The Miracles of the Namiya General Store', 'ナミヤ雑貨店の奇蹟', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/7ebBoOAva5PiPkkG9zkDzCpqCt3.jpg', 'https://image.tmdb.org/t/p/original/1oKzizFUAQurTaCvhJFPSKuDvwc.jpg', 'In 2012, Atsuya and his 2 childhood friends do something bad and run into an old general store. They decide to stay there until the morning. Late into the night, Atsuya sees a letter in the mailbox. The letter is addressed to the Namiya General Store and the letter was written by someone to consult about worries. Incredibly, the letter was written 32 years ago. The mailbox is somehow connected to the year 1980. Atsuya and his friends decide to write a reply and place their letter in the mailbox.', NULL, NULL, 1.8581, 6.9, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
