INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6709, NULL, NULL, 1377, 'Spec Ops: The Line', 'Spec Ops: The Line', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2acb.jpg', NULL, 'A third-person shooter in which three American soldiers led by Capt. Walker are sent to Dubai in order to recover whoever remains of an infantry unit, the 33rd Battalion, until they decide to take action against the militants situated in the city. As they progress, however, the logistical and ethical complexity of their objective deepens, and their perception of themselves, and their enemy, is put into question.', 'https://www.igdb.com/games/spec-ops-the-line', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, NULL, 0, 6.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
