INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6723, 17238, 'tt0092637', NULL, 'The Belly of an Architect', 'The Belly of an Architect', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/gjS08AHtZ7b44WC2NCuYWpJRoCM.jpg', 'https://image.tmdb.org/t/p/original/cLSMoqNcBtwIAvyG5rirqfRkkkP.jpg', 'Stourley Kracklite, a driven, detail-obsessed architect, travels from America to Rome with his much younger wife, Louisa, to oversee an architectural homage to a personal hero, 18th-century master builder Etienne-Louis Boullée. En route by train, Stourley and Louisa conceive a much-wanted child — but Stourley''s obsession with his wife''s expanding belly, her perceived infidelity, and his own recurrent bouts of abdominal pain reach epic and dangerous proportions.', NULL, NULL, 1.1242, 6.828, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
