INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6731, 20077, 'tt0472219', NULL, 'The Batman vs. Dracula', 'The Batman vs. Dracula', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/8uKIqZBXfxhflenI2LkNZIHUp7I.jpg', 'https://image.tmdb.org/t/p/original/326o6Tw8QHP6TtIXqU56dDYgnzL.jpg', 'Gotham City is terrorized not only by recent escapees Joker and Penguin, but by the original creature of the night, Dracula! Can Batman stop the ruthless vampire before he turns everyone in the city, including The Caped Crusader, Joker and Penguin, into his mindless minions?', NULL, NULL, 2.6085, 7.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
