INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6750, 25530, 'tt0459929', NULL, 'First on the Moon', 'Первые на Луне', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/pPRzltQzMNKmcZ6WQ4BZRle0CZd.jpg', 'https://image.tmdb.org/t/p/original/AaMngHV8WXJr2BGzqO5OFUDrrhA.jpg', 'In spring 1938 in the mountains in the north of Chile a fiery UFO, later named "Chilean Sphere ", fell down. The investigation of this episode, made by a film crew, has led to a sensational discovery. It appeared that before the Second World War (in the thirties) in the USSR a secret space program had been developed. The Soviet scientists and military authorities managed to launch the first spacecraft 23 years prior to Jury Gagarin''s flight! "The First on the Moon" tells about everyday life, heroic deeds and tragedy of the first group of the Soviet cosmonauts. It is the first Russian film shot in a very rare genre ''mockumentary'' or ''documentary fiction''.', NULL, NULL, 0.4029, 5.074, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
