INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6752, 16082, 'tt0090319', NULL, 'White Nights', 'White Nights', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/ampweVzwwWQHSwFvz2YTyRIrJza.jpg', 'https://image.tmdb.org/t/p/original/nEs4WAMmfsywZWLkJHtKQh3LDpa.jpg', 'After his plane crashes in Siberia, a Russian dancer, who defected to the West, is held prisoner in the Soviet Union. The KGB keeps him under watch and tries to convince him to become a dancer for the Kirov Academy of Ballet again. Determined to escape, he befriends a black American expatriate and his pregnant Russian wife, who agree to help him escape to the American Embassy.', NULL, NULL, 2.4846, 6.7, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
