INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6754, 11863, 'tt0113451', NULL, 'Jade', 'Jade', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/8KWiZKDYpAgh8n27lanvTuDquyX.jpg', 'https://image.tmdb.org/t/p/original/k19u7EVyMqhfQrH9KMlyCNbnvBZ.jpg', 'When a prominent art dealer is found murdered, the man''s death leads to an intriguing investigation steeped in sex, corruption and crime. District Attorney David Corelli gets assigned to the case and discovers that a key suspect is his ex-lover Katrina Gavin, a beautiful psychologist who has settled down with his old friend and peer. As Corelli gets deeper into the case, he uncovers dark secrets with far-reaching implications.', NULL, NULL, 2.558, 5.529, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
