INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6757, 20220, 'tt0098961', NULL, '1001 Nights', 'Les 1001 nuits', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/wFubQZcMS5ZEPX3kf1XatDQPAmy.jpg', 'https://image.tmdb.org/t/p/original/vzF3VTGRMd4Iz7VDCvZyTqfy6Pe.jpg', 'Sheherazade has been married to a ruler who wants many wives, but only one at a time. Consequently, as soon as he has bedded them, he has them put to death. In most retellings, the girl staves off this unfortunate conclusion by putting off the connubial event for a thousand and one nights, telling irresistible stories instead. In this one, she gets hold of a magic lamp.', NULL, NULL, 2.2265, 5.182, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6758, 19103, 'tt0450972', NULL, 'As You Like It', 'As You Like It', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/628YkM5wHmunTdXANWgJEJYbFdf.jpg', 'https://image.tmdb.org/t/p/original/cBpCtxMAViuM0uZYjD0yoRmAkgQ.jpg', 'Witty, playful and utterly magical, the story is a compelling romantic adventure in which Rosalind and Orlando''s celebrated courtship is played out against a backdrop of political rivalry, banishment and exile in the Forest of Arden - set in 19th-century Japan.', NULL, NULL, 1.1833, 5.77, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6759, 1136791, 'tt10846056', NULL, 'City of Lost Children', 'City of Lost Children', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/p0PPB4e7mrZUcRwRUkYb0Z74kad.jpg', NULL, 'City of Lost Children is a near future thriller set in a refugee camp for kids in the UK. We follow Dami and Azra as they negotiate the chaos of the camp, desperately trying to find a home for Dami before Azra is deported the next day.', NULL, NULL, 0.8107, 0.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6760, 42236, 'tt0074291', NULL, 'Fellini''s Casanova', 'Il Casanova di Federico Fellini', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/ygTsnjWEUY8fbXzFWIh07eEHf3w.jpg', 'https://image.tmdb.org/t/p/original/nn84IU1JFwvfcVhQ08teDM080yd.jpg', 'Imprisoned for practicing black magic, writer and adventurer Giacomo Casanova escapes and wanders Europe, using his fluid sexuality to find his place in life amid a variety of eccentric and strange characters.', NULL, NULL, 1.8298, 6.872, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6761, 9606, 'tt0293416', NULL, 'Metropolis', 'メトロポリス', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/41WtqvaObaYE3RuqgBfQFPV3aV1.jpg', 'https://image.tmdb.org/t/p/original/1FBByew9RnXQ2HFqf7b6EWkyzTP.jpg', 'In the midst of societal conflict in the futuristic city of Metropolis, Kenichi and his uncle Shunsaku Ban set out to uncover the mystery behind the first human-like robot, Tima.', NULL, NULL, 2.7389, 7.154, 0, 2.03, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6762, 11971, 'tt0107616', NULL, 'Much Ado About Nothing', 'Much Ado About Nothing', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/tvltGP6vYOkHdURag0jPSjhPUAV.jpg', 'https://image.tmdb.org/t/p/original/dktr46Mbdr2DpHmqe5ruUmiu6qN.jpg', 'In this Shakespearean farce, Hero and her groom-to-be, Claudio, team up with Claudio''s commanding officer, Don Pedro, the week before their wedding to hatch a matchmaking scheme. Their targets are sharp-witted duo Benedick and Beatrice -- a tough task indeed, considering their corresponding distaste for love and each other. Meanwhile, meddling Don John plots to ruin the wedding.', NULL, NULL, 3.9285, 6.943, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
