INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6764, 1354518, 'tt33350512', NULL, '100 Nights of Hero', '100 Nights of Hero', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/yJKvHYz0b0ebfPh6LYBO3gGsccZ.jpg', 'https://image.tmdb.org/t/p/original/skmFqH67nh8zJacf7WcR204Kgvl.jpg', 'When a charming house guest arrives at a remote castle, the delicate dynamic between a neglectful husband, his innocent bride Cherry and their devoted maid Hero is thrown into chaos.', NULL, NULL, 1.9128, 6.114, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6765, 65592, 'tt0229664', NULL, 'Princes and Princesses', 'Princes et Princesses', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/gP1PDJmbsF5J2teuond2OtRiEaC.jpg', 'https://image.tmdb.org/t/p/original/6W2jH4hcqbNto9uTyda8ccNj1oJ.jpg', 'In this episodic animated fantasy from France, an art teacher interprets a series of six fairy tales (each involving a prince or princess) with the help of two precocious students. Princes and Princesses was created using a special style of cutout animation, with black silhouetted characters performing the action against backlit backdrops in striking colors.', NULL, NULL, 1.2318, 7.7, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
