INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6775, NULL, NULL, 14593, 'Hollow Knight', 'Hollow Knight', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobfzp.jpg', NULL, 'A 2D metroidvania with an emphasis on close combat and exploration in which the player enters the once-prosperous now-bleak insect kingdom of Hallownest, travels through its various districts, meets friendly inhabitants, fights hostile ones and uncovers the kingdom''s history while improving their combat abilities and movement arsenal by fighting bosses and accessing out-of-the-way areas.', 'https://www.igdb.com/games/hollow-knight', '["Xbox Series X|S", "PlayStation 4", "Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Wii U", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6776, 127235, 'tt9737326', NULL, 'Invasion', 'Invasion', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/1PdNB3rYTcf8VXc8rcmZ0SeYxSq.jpg', 'https://image.tmdb.org/t/p/original/i9IEOD1Li1y89xRHKH9kiE8dt9z.jpg', 'Earth is visited by an alien species that threatens humanity''s existence. Events unfold in real time through the eyes of five ordinary people across the globe as they struggle to make sense of the chaos unraveling around them.', NULL, NULL, 25.8415, 7.079, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6777, NULL, NULL, 533, 'Dishonored', 'Dishonored', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabgu.jpg', NULL, 'Dishonored is an immersive first-person action game that casts you as a supernatural assassin driven by revenge. With Dishonored’s flexible combat system, creatively eliminate your targets as you combine the supernatural abilities, weapons and unusual gadgets at your disposal. Pursue your enemies under the cover of darkness or ruthlessly attack them head on with weapons drawn. The outcome of each mission plays out based on the choices you make.', 'https://www.igdb.com/games/dishonored', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, NULL, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6778, 1390382, 'tt34688195', NULL, 'Couture', 'Coutures', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/4QNJXfb9Kfo2dn0pz9p1S2KkgBm.jpg', 'https://image.tmdb.org/t/p/original/9GBiwvuJahvlfEQtuGhpS384Ei5.jpg', 'In the frenzy of Fashion Week, three women cross paths in Paris, grappling with the world''s tragedies and the questions of their lives: Maxine, an American film director in her forties, discovers she has cancer; Ada, a young South Sudanese model, escapes a predetermined destiny to be thrust into a deceptive universe and French makeup artist Angèle, a small hand working in the shadows of the catwalks, dreams of escaping her life.', NULL, NULL, 12.1858, 6.176, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6779, 21309, 'tt0091860', NULL, 'River''s Edge', 'River''s Edge', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/bT68aKa9d7zDF7Z8MaskbWBRqzb.jpg', 'https://image.tmdb.org/t/p/original/rQehKh69FjD7m4uAlXab0JGCWZT.jpg', 'A group of high-school friends must come to terms with the fact that one of them, Samson, killed another, Jamie. Faced with the brutality of death, each must decide whether to turn their friend in to the police, or to help him escape the consequences of his dreadful deed.', NULL, NULL, 2.4918, 6.527, 0, 2.015, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6780, 41044, 'tt0464061', NULL, 'I''m Reed Fish', 'I''m Reed Fish', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/uAKVpiAKzqwfkqZgckoI1mGcrmT.jpg', 'https://image.tmdb.org/t/p/original/udr5oGwXsCj9uYIodBPk6zXcEzz.jpg', 'When an old high school crush returns to his small hometown, Reed Fish''s once simple, calculated life begins to unravel. A drunken incident prompts Reed''s fiancée and the entire town to turn against him.', NULL, NULL, 1.2442, 5.6, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6781, 14709, 'tt0139699', NULL, 'Varsity Blues', 'Varsity Blues', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/g2jX2Xmx7drbc6J9MLJEBghR7Mg.jpg', 'https://image.tmdb.org/t/p/original/rTlMsaE2MQ8NG2cs0bEkwVhMOrV.jpg', 'In small-town Texas, high school football is a religion, 17-year-old schoolboys carry the hopes of an entire community onto the gridiron every Friday night. When star quarterback Lance Harbor suffers an injury, the Coyotes are forced to regroup under the questionable leadership of John Moxon, a second-string quarterback with a slightly irreverent approach to the game.', NULL, NULL, 2.7963, 6.144, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6782, 10135, 'tt0098206', NULL, 'Road House', 'Road House', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/n7Ra0BRYQVn47kiqOMyS8vdY0QS.jpg', 'https://image.tmdb.org/t/p/original/cUrFALlZP6Zh5SYRPSUnOYXfMhr.jpg', 'The Double Deuce is the meanest, loudest and rowdiest bar south of the Mason-Dixon Line, and Dalton has been hired to clean it up. He might not look like much, but the Ph.D.-educated bouncer proves he''s more than capable – busting the heads of troublemakers and turning the roadhouse into a jumping hot spot. But Dalton''s romance with the gorgeous Dr. Clay puts him on the bad side of cutthroat local big shot Brad Wesley.', NULL, NULL, 5.1567, 6.769, 0, 16.76375, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6783, 50501, 'tt0177885', NULL, 'Killer Bud', 'Killer Bud', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/4zqs9e5hPsgHaCOW1UXSWZWPyMf.jpg', 'https://image.tmdb.org/t/p/original/baATk3c4bhW6vKA4RZapSk8TxaB.jpg', 'After losing another job, two idiots embark on an adventure of mythic proportion: to acquire "Feed Bags," the discontinued entire-meal-in-a-bag, to impress their two equally dim-witted dates. When the only convenience store in town that carries the discontinued food item is found closed, Waylon and Buzz break in and can''t break out.', NULL, NULL, 0.3098, 5.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6784, 33542, 'tt0113326', NULL, 'Rumble in the Bronx', '紅番區', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/1nAfchiXHQB3iyhK8fCJJEnNs5A.jpg', 'https://image.tmdb.org/t/p/original/5ftRls3IbR1kXnasqJEJL63LVsc.jpg', 'Keong comes from Hong Kong to visit New York for his uncle''s wedding. His uncle runs a market in the Bronx and Keong offers to help out while Uncle is on his honeymoon. During his stay in the Bronx, Keong befriends a neighbor kid and beats up some neighborhood thugs who cause problems at the market. One of those petty thugs in the local gang stumbles into a criminal situation way over his head.', NULL, NULL, 6.5224, 6.862, 0, 3.05, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6785, 13841, 'tt0091817', NULL, 'Rad', 'Rad', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/yg7TR7U4f2xRrVrM0IyDUGuFSHa.jpg', 'https://image.tmdb.org/t/p/original/y4Kw8lT0BEBHaEm4hqw12AKJNoZ.jpg', 'A BMX racer, who lives in a small town with his mother and sister, is faced with a tough decision, qualify for Helltrack or take his SATs in order to attend college.', NULL, NULL, 1.9379, 6.526, 0, 2.065, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6786, 35371, 'tt0092085', NULL, 'Thrashin''', 'Thrashin''', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/7yq7P9bqtbMGkWoikQDegyepuDh.jpg', 'https://image.tmdb.org/t/p/original/ouoi01NpFt3WxpfIwfOVQ9p8gKk.jpg', 'Corey and his band of skater buddies sometimes make mischief, but they''re more interested in girls and having fun on their boards than in getting into any real trouble. Notorious enemy crew the Daggers, led by Tommy Hook, get their kicks terrorizing the locals at Venice Beach. When Corey starts dating Tommy''s kid sister Chrissy, the Daggers are furious. The boys then take their beef to the "L.A. Massacre," a deadly skate race down a canyon road.', NULL, NULL, 2.0821, 6.291, 0, 2.025, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6787, 5549, 'tt0100502', NULL, 'RoboCop 2', 'RoboCop 2', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/nhqBxhOJXUJeFsyLxTFkctH9H5F.jpg', 'https://image.tmdb.org/t/p/original/cT0YCYCtAQC8wi56VWK1JRGgk3a.jpg', 'After a successful deployment of the RoboCop Law Enforcement unit, OCP sees its goal of urban pacification come closer and closer, but as this develops, a new narcotic known as "Nuke" invades the streets led by God-delirious leader Cane. As this menace grows, it may prove to be too much for Murphy to handle. OCP tries to replicate the success of the first unit, but ends up with failed prototypes with suicidal issues... until Dr. Faxx, a scientist straying away from OCP''s path, uses Cane as the new subject for the RoboCop 2 project, a living God.', NULL, NULL, 6.6071, 6.0, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6788, 41613, 'tt0337585', NULL, 'Bomb the System', 'Bomb the System', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/r4wOlMjNTcCYLXX7Nzd3G6ECyFM.jpg', NULL, 'Anthony ‘Blest’ (Mark Webber) is one of the most talented and notorious graffiti artists in New York City. Despite the tragic loss of his older brother during a nightly ''bombing'' foray with a graffiti crew, Anthony has the same insatiable addiction. With the other members of his ‘crew,’ Anthony parties, shoplifts spray-paint and ''tags'' virgin walls with his signature ''Blest.'' He does his best to avoid run-ins with the cops and hostile rival crews, but he can’t avoid the pressure from his mother to attend college, and from his girlfriend to leave New York with her. As tensions rise, a physical threat from the cops causes the crew to intensify their bombing excursions, calling an all out war on the city. When the inevitable confrontation happens, a tragedy results that pushes Anthony to make a decision that has even darker consequences.', NULL, NULL, 0.5742, 7.0, 0, 2.015, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6789, 1634, 'tt0106965', NULL, 'Free Willy', 'Free Willy', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/9iBgd9gi9ztWiVcYSG6zl8wDFBN.jpg', 'https://image.tmdb.org/t/p/original/mXkUfzJfdWx9y4Zlm7wsvQ0uvYo.jpg', 'When maladjusted orphan Jesse vandalizes a theme park, he is placed with foster parents and must work at the park to make amends. There he meets Willy, a young Orca whale who has been separated from his family. Sensing kinship, they form a bond and, with the help of kindly whale trainer Rae Lindley, develop a routine of tricks. However, greedy park owner Dial soon catches wind of the duo and makes plans to profit from them.', NULL, NULL, 7.9528, 6.206, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6790, 2403, 'tt0208616', NULL, 'Downtown', 'Downtown', 'tv', 1999, 'https://image.tmdb.org/t/p/w500/p25aEI1cdZfi0Rzo5CTxcvX4tMA.jpg', 'https://image.tmdb.org/t/p/original/zrImqBL91Q9cEvqOxuY9otmQN9I.jpg', 'Downtown is an animated series on MTV on urban life, based on interviews with real people. The show follows a diverse and multiracial cast who live in New York City, and presents their everyday lives through quirky, humorous, and imaginative perspectives from the characters. It was created by Chris Prynoski, a former animator on Beavis and Butt-Head and produced by David McGrath. In 2000, Downtown was nominated for an Emmy in the category of outstanding animated program.

Downtown faced a similar fate to many of MTV''s other cartoons - it only lasted one season. The use of an original score rather than licensed music makes a sanctioned DVD release unlikely.

Some of the show''s staff have gone on to work on the action animated series Megas XLR, which uses the same quirky humor found in Downtown as well as the character Goat, reprised by Scott Rienecker.', NULL, NULL, 4.1014, 7.979, 0, 2.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6791, 9070, 'tt0113820', NULL, 'Mighty Morphin Power Rangers: The Movie', 'Mighty Morphin Power Rangers: The Movie', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/pcLbHqs80dchv0byHivhdwHKEup.jpg', 'https://image.tmdb.org/t/p/original/7n6RzJfPGnSGsHidO2gUWYgs1TT.jpg', 'Six incredible teens out-maneuver and defeat evil everywhere as the Mighty Morphin Power Rangers, but this time the Power Rangers may have met their match when they face off with Ivan Ooze, the most sinister monster the galaxy has ever seen.', NULL, NULL, 3.7251, 5.886, 0, 2.015, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6792, 15797, 'tt0107750', NULL, 'Only the Strong', 'Only the Strong', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/pPWV5rBhCgzlzhwkpdRG7a7UZqt.jpg', 'https://image.tmdb.org/t/p/original/k7wQcxa6KN5EmAdxj1tWgy7odBg.jpg', 'Former Green Beret Louis Stevens returns to his hometown of Miami after completing military service in Brazil, only to learn that his old high school has become a haven for gangs and drug dealers. After Stevens uses his capoeira skills to kick several drug dealers off of the school property, Kerrigan, one of Stevens'' old teachers, sees the impact that Stevens has on the students. Kerrigan gives him the task of teaching Capoeira to a handful of the worst at-risk students at the school.', NULL, NULL, 2.2589, 6.923, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6793, 2005, 'tt0105417', NULL, 'Sister Act', 'Sister Act', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/xZvVSZ0RTxIjblLV87vs7ADM12m.jpg', 'https://image.tmdb.org/t/p/original/bNiBuekwqwNKFGSqlJRDZIF4ADB.jpg', 'When lively lounge singer Deloris sees her mobster beau commit murder, she is relocated for her protection. Set up in the guise of a nun in a California convent, she proceeds to upend the quiet lives of the resident sisters.', NULL, NULL, 11.2845, 6.832, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
