INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6795, 13064, 'tt0106233', NULL, 'Airborne', 'Airborne', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/4TPCzvOoQmmParPjgHCiqqiVYIJ.jpg', 'https://image.tmdb.org/t/p/original/byQFTtskbR9COpluK1p3oImdsBt.jpg', 'Good-natured teen surfer Mitchell Goosen finds himself staying with his aunt and uncle in Cincinnati, Ohio when his parents head to Australia for work. There he meets his cousin, Wiley, and together they try to navigate the perils of high school—avoid the bullies, get the girl, and win a little respect.', NULL, NULL, 2.0815, 6.022, 0, 4.0275, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
