INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6797, 461615, 'tt4717402', NULL, 'MFKZ', 'Mutafukaz', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/oSMIKsznGYzGfdl611kgEJF889.jpg', 'https://image.tmdb.org/t/p/original/1HwTbEN3SFiFWxChqVXddxquKHf.jpg', 'Angelino is just one of thousands of deadbeats living in Dark Meat City. But an otherwise unremarkable scooter accident caused by a beautiful, mysterious stranger is about to transform his life... into a waking nightmare! He starts seeing monstrous forms prowling around all over the city... Is Angelino losing his mind, or could an alien invasion really be happening this quietly...?', NULL, NULL, 1.8432, 7.125, 0, 2.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6798, 10406, 'tt0104187', NULL, 'Encino Man', 'Encino Man', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/y8HtL6pyjfODdHOFgciFVFmt8Eq.jpg', 'https://image.tmdb.org/t/p/original/2C4b0mHxy420fBk5xvbBwEf03bY.jpg', 'High school misfits Stoney and Dave discover a long-frozen primeval man buried in their backyard. But the thawed-out Link—as the boys have named him—quickly becomes a wild card in the teens'' already zany Southern California lives. After a shave and some new clothes, Link''s presence at school makes the daily drudgery a lot more interesting.', NULL, NULL, 7.7415, 5.799, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
