INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6808, 67994, '', NULL, 'Motorcycle Mania 2', 'Motorcycle Mania 2', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/jaisTeuJj7cxqEvtpkn7KkDkMX7.jpg', NULL, 'A lone biker rides north. He''s on the blacktop under an endless blue sky as he races across California''s Mojave Desert. The rider is helmetless, defying the law, and his brawny tattooed arms and fists, clamp down hard as he blasts down the road at over 100 mph. Like a pony express rider, this man is on a mission. Two months ago, he vowed he''d build a chrome monster and ride it from Long Beach, Calif., all the way to Sturgis, S.D. — 1,400 miles nonstop. So, in just eight weeks, this biker/designer created an amazing, one-of-a-kind, sleek, mean chopper from the ground up, and today he''s underway. Three hundred miles from home, with 1,100 miles to go, he is headed for the biggest, raunchiest, loudest, wildest, craziest motorcycle jamboree in the world: the Sturgis 2001 Black Hills Classic.', NULL, NULL, 0.1922, 0.0, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
