INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6835, 10017, 'tt0092240', NULL, 'The Wraith', 'The Wraith', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/vHrNnqqRYWzkkrJV8MtmUGgC4Kk.jpg', 'https://image.tmdb.org/t/p/original/oRwBASyG34mwSpIR1CSao123Xi4.jpg', 'Packard Walsh and his motorized gang control and terrorize an Arizona desert town where they force drivers to drag-race so they can ''win'' their vehicles. After Walsh beats the decent teenager Jamie Hankins to death after finding him with his girlfriend, a mysterious power creates Jake Kesey, an extremely cool motor-biker who has a car which is invincible. Jake befriends Jamie''s girlfriend Keri Johnson, takes Jamie''s sweet brother Bill under his wing and manages what Sheriff Loomis couldn''t; eliminate Packard''s criminal gang the hard way...', NULL, NULL, 4.7868, 6.382, 0, 11.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
