INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6846, 365045, 'tt3700392', NULL, 'Heidi', 'Heidi', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/ue6L0x3C9V4c5kIiWnEIOPwtGhw.jpg', 'https://image.tmdb.org/t/p/original/j61P3ty6dOWygdPSneEH56BrkSD.jpg', 'Heidi, is an eight-year-old Swiss orphan who is given by her aunt to her mountain-dwelling grandfather. She is then stolen back by her aunt from her grandfather to live in the wealthy Sesemann household in Frankfurt, Germany as a companion to Klara, a sheltered, disabled girl in a wheelchair. Heidi is unhappy but makes the best of the situation, always longing for her grandfather.', NULL, NULL, 10.0509, 7.2, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6847, 27985, 'tt0113028', NULL, 'Far from Home: The Adventures of Yellow Dog', 'Far from Home: The Adventures of Yellow Dog', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/bHtNHOiSmfX1KlJwc9Jvc8sYcjB.jpg', 'https://image.tmdb.org/t/p/original/bDuosrdJBpHvNMD9pzWQcD4ldBv.jpg', 'Teenager Angus adopts a stray dog and names him Yellow. Several days later, while travelling along the coast of British Columbia with Angus''s father, John, the boy and dog become stranded when turbulent waters capsize their boat. Angus''s parents relentlessly badger rescue teams. Angus, schooled by his father in wilderness survival skills, and assisted by the intelligent Yellow Dog, tries to attract rescuers.', NULL, NULL, 1.0013, 6.188, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6848, 96465, 'tt0090299', NULL, 'Waterwalker', 'Waterwalker', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/sexRHjLCMwxF8AVM3IrkwIeF083.jpg', 'https://image.tmdb.org/t/p/original/ocDJqbFR4Gj08UH30Fkwwyx33Lg.jpg', 'Naturalist Bill Mason on his journey by canoe into the Ontario wilderness. The filmmaker and artist begins on Lake Superior, then explores winding and sometimes tortuous river waters to the meadowlands of the river''s source. Along the way, Mason paints scenes that capture his attention and muses about his love of the canoe, his artwork and his own sense of the land. Mason also uses the film as a commentary on the link between God and nature and the vast array of beautiful canvases God created for him to paint. Features breathtaking visuals and exciting whitewater footage, with a musical score by Bruce Cockburn.', NULL, NULL, 0.8657, 8.333, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
