INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6851, 481848, 'tt7504726', NULL, 'The Call of the Wild', 'The Call of the Wild', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/33VdppGbeNxICrFUtW2WpGHvfYc.jpg', 'https://image.tmdb.org/t/p/original/1GZCV0dwIoAn6jpWPfVAbeMTVC2.jpg', 'Buck is a big-hearted dog whose blissful domestic life is turned upside down when he is suddenly uprooted from his California home and transplanted to the exotic wilds of the Yukon during the Gold Rush of the 1890s. As the newest rookie on a mail delivery dog sled team—and later its leader—Buck experiences the adventure of a lifetime, ultimately finding his true place in the world and becoming his own master.', NULL, NULL, 6.7582, 7.511, 0, 2.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
