INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6853, 21299, 'tt0092638', NULL, 'Benji the Hunted', 'Benji the Hunted', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/g4mlRGzUKCXfRDUJqSRPY0mKPMC.jpg', 'https://image.tmdb.org/t/p/original/iPAMreszojqokGFvXL9hzQ6xliQ.jpg', 'Benji has become stranded on a remote island after a boating accident. He finds himself struggling to survive in the wilderness, avoiding close encounters with a wolf, a bear, and a territorial female cougar with her cub.', NULL, NULL, 1.6543, 6.551, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6854, 108839, 'tt0973809', NULL, 'Headhunter: The Assessment Weekend', 'Headhunter: The Assessment Weekend', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/4ecOCvJbrKp7NlrAXNzE3LGYhyg.jpg', NULL, 'A motley group of business students in Berlin, Germany sign up for Takahashi Corp.''s assessment weekend, hoping to land one of the coveted spots with the consulting company. Under the watchful eye of a company psychologist, the team-working and improvisational skills of the aspirants will be put to the test in a survival-type situation. But nothing goes according to plan - the group arrives to find the base camp completely destroyed. Trapped in the woods with no food, no shelter and no way to communicate with the outside world, the real characters of the students come to light, as one by one, they start to lose their heads...', NULL, NULL, 0.393, 3.5, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6855, 630392, 'tt9907782', NULL, 'The Cursed', 'The Cursed', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/bewmBcjJxHeipS1PNu9Lfyvt3zY.jpg', 'https://image.tmdb.org/t/p/original/hPurpFeAkvkvWYRVSDYGDaDSgva.jpg', 'In the late 19th century, a brutal land baron slaughters a Roma clan, unleashing a curse on his family and village. In the days that follow, the townspeople are plagued by nightmares, the baron''s son goes missing, and a boy is found murdered. The locals suspect a wild animal, but a visiting pathologist warns of a more sinister presence lurking in the woods.', NULL, NULL, 4.915, 6.562, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
