INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6857, 1394, 'tt0086022', NULL, 'Nostalgia', 'Ностальгия', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/fCYSidPXp3LpDa9wlLNv0gZvjyF.jpg', 'https://image.tmdb.org/t/p/original/z0ZAEC2aZuflzua3HOSygVzE6Jq.jpg', 'Russian poet Andrei Gorchakov journeys through Italy with his interpreter Eugenia to research the life of an 18th-century Russian composer who once lived abroad. Isolated and consumed by an unrelenting longing for his homeland, Andrei becomes drawn to Domenico, a radical mystic obsessed with spiritual redemption. Through austere imagery and extended temporal rhythms, Tarkovsky examines exile, memory, and the profound melancholy of being unable to belong fully to either place or language.', NULL, NULL, 2.489, 7.8, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
