INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6861, 15143, 'tt0094006', NULL, 'Some Kind of Wonderful', 'Some Kind of Wonderful', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/6z6ZUrwbAJl9Nq43OY77O7iY80x.jpg', 'https://image.tmdb.org/t/p/original/k5LISwQzFyNiw0o1G0azI3YmFnO.jpg', 'Keith Nelson, an artsy high school outcast, tries to land a date with popular girl Amanda Jones with some help from his tomboy best friend, Watts. However, Watts realizes she likes Keith as more than just a friend and tries to convince him to stop pursuing Amanda. Matters are further complicated when Keith''s invitation draws the ire of Amanda''s rich yet snobby ex-boyfriend, Hardy Jenns, who makes plans to get even.', NULL, NULL, 4.0445, 6.838, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
