INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6863, 245859, 'tt2141751', NULL, 'God Help the Girl', 'God Help the Girl', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/7HvJyWDP5OhgAjrg1qs1dHPV9rd.jpg', 'https://image.tmdb.org/t/p/original/yMh8badxy3ekUavcBNW37hjWE1d.jpg', 'Eve is a catastrophe—low on self-esteem but high on fantasy, especially when it comes to music. Over the course of one Glasgow summer, she meets two similarly rootless souls: posh Cass and fastidious James, and together they form a band.', NULL, NULL, 1.0515, 6.547, 0, 1.02, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6864, 1465063, 'tt36583977', NULL, 'Forgotten Island', 'Forgotten Island', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/kW1fH2jZZM5tVHwNaDdUOUXJvWU.jpg', 'https://image.tmdb.org/t/p/original/cNICUho5uiAGkfCAQq1ihyaMla4.jpg', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa will race to find a way to leave the island before they forget each other forever.', NULL, NULL, 7.145, 0.0, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6865, 587357, 'tt33996352', NULL, 'Miss Moxy', 'Miss Moxy', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/lKxmXNfjzNchKi3F8rJpUpZBtR7.jpg', 'https://image.tmdb.org/t/p/original/ol2xAdFJa9Lvf70HtaBIiapMC7x.jpg', 'From the cobbled streets of Paris to the wild countryside of Europe, follow Miss Moxy — a pampered cat with a whole lot of cattitude — as she’s thrown into the adventure of a lifetime. Lost far from home, she must team up with a goofy dog and a wise old bird to find her way back… and discover who she truly is along the way.', NULL, NULL, 1.9705, 8.1, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6866, 39859, 'tt1663676', NULL, 'Awkward.', 'Awkward.', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/7PLO6PdGmfKiV3KER2Rd08Ga8kM.jpg', 'https://image.tmdb.org/t/p/original/yFFW6MtYRjBHppYWskmG81pR7xV.jpg', 'An irreverent look at the conflict, chaos and humor that defines teenage life through the eyes of 15-year-old Jenna Hamilton whose life begins to change when a simple accident becomes an epic misunderstanding and is blown way out of proportion. Narration in the first-person voice of Jenna''s blog posts captures the humor within the struggles and experiences everyone can relate to from their formative years.', NULL, NULL, 12.9582, 7.4, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6867, 12172, 'tt1093824', NULL, 'Encounters at the End of the World', 'Encounters at the End of the World', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/tAkl9GAUQoJaQQu2dtSQdQJ5yS9.jpg', 'https://image.tmdb.org/t/p/original/k5wG09wKslKid7EqxJ351oFytFx.jpg', 'Acclaimed filmmaker Werner Herzog travels to Antarctica, where he finds a desolate, beautiful landscape, largely untouched by human hands, and a group of truly unique people who risk their lives to study it. Centered at McMurdo Station, the United States'' largest Antarctic research center, Herzog explores the minds of the scientists willing to abandon civilization and endure volatile conditions to learn more about the continent''s wildlife and awe-inspiring natural wonders.', NULL, NULL, 2.062, 7.475, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
