INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6874, 686632, 'tt13143740', NULL, 'Dream Journal 2016–2019', 'Dream Journal 2016–2019', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/zAN2mu6n8I6QYpy24mpTooAZ9ls.jpg', 'https://image.tmdb.org/t/p/original/yvBS0agVGfIhWE1qHWT6gGlBqz8.jpg', 'This single-channel video explores the effects of technology and information overload on the contemporary psyche. Set in a virtual tech-noir urban space populated by strange hybrids of non-humans and augmented people, part of the expansive, fractured narrative focuses on the continued adventures of Xanax Girl and her search for her companion—a hybrid dog/seal with the head of a boy—who has been abducted. The film, which arose from the artist’s daily practice of animating his dreams using hobbyist 3D software, weaves together deep-web imagery with hardboiled detective story tropes and repressed libidinal fantasies to create a nightmarish vision of an internet addict’s unconscious. The film features an original score by Oneohtrix Point Never and James Ferraro.', NULL, NULL, 0.3689, 0.0, 0, 1.07, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6875, 23056, 'tt0332318', NULL, 'Pinocchio 3000', 'Pinocchio 3000', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/qtTJzlzJf5FuY4qWjleSsLIgYjD.jpg', 'https://image.tmdb.org/t/p/original/9viXmNTZczTzVQbQpImNr1hUsxO.jpg', 'This is the story of a little robot known as Pinocchio 3000 whose greatest wish is to become a real boy. The year is 3000. Geppetto, with the help of his faithful assistant, Spencer the cyber penguin, and by the holographic fairy Cyberina, creates Pinocchio, a prototype superrobot equipped for emotions. But before he can be given a heart and become a real boy, Cyberina insists that Pinocchio learn the difference between right and wrong.', NULL, NULL, 3.1085, 4.403, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6876, 165220, 'tt0167285', NULL, 'The Mind''s Eye', 'The Mind''s Eye', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/8owGK5kSi9Hodybs3fQjRMZq0ht.jpg', 'https://image.tmdb.org/t/p/original/ms4y2vhF3uNLB3sWMvQ6NsAkFBf.jpg', 'The Mind''s Eye is a compilation of experimental computer animations from when such technology was in its early infancy. The animations are from various studios, having been arranged in a sort of "2001" evolution-timeline theme, and set to synthesized music. These pioneering CGI projects later gave rise to films such as Toy Story, A Bug''s Life, Antz, and Shrek.', NULL, NULL, 0.3951, 7.5, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
