INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6902, 36124, 'tt1014809', NULL, 'Until the Light Takes Us', 'Until the Light Takes Us', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/sPg2fepwnhGzhRbVZ7bYoneOYaK.jpg', 'https://image.tmdb.org/t/p/original/tTOYeamnYF9K0u7y1yj209H6Nad.jpg', 'Chronicles the history, ideology and aesthetic of Norwegian black metal, a musical subculture infamous as much for a series of murders and church arsons as it is for its unique musical and visual aesthetics. This is the first film to truly shed light on a movement that has heretofore been shrouded by rumor and obscured by inaccurate and shallow depictions. Featuring exclusive interviews with the musicians themselves, Until the Light Takes Us explores every aspect of the controversial movement that has captured the attention of the world.', NULL, NULL, 0.6758, 6.759, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
