INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6919, 514, 'tt0101053', NULL, 'Brides of Christ', 'Brides of Christ', 'tv', 1991, 'https://image.tmdb.org/t/p/w500/xST1yLwvciKxMpQHqigSnMmCod3.jpg', 'https://image.tmdb.org/t/p/original/5P8cJhZtlrOzy7jzNwkcZCXIYje.jpg', 'Diane, a young woman growing up in Australia in the mid 1960s, walks away from her fiancé to join a convent after being sure she has a calling to the faith. The Catholic Church and its followers are struggling with huge changes. The Pope has died, there is war in Vietnam and mandatory conscription, there is the Vatican controversy on abortion and contraception, and the changing face of the Church as a whole. Told in six parts, Diane faces her own demons and has to finally decide if she can teach what the Church preaches, or if it''s simply impossible for her to reconcile all the contradictions of the faith and uphold her vow of obedience.', NULL, NULL, 1.6511, 7.25, 0, 1.01, '2026-08-03 14:31:56', '2026-08-03 14:31:56');
