UPDATE "recommendations" SET "tmdb_id"=11020, "imdb_id"='tt0073540', "igdb_id"=NULL, "title"='Picnic at Hanging Rock', "original_title"='Picnic at Hanging Rock', "media_type"='movie', "release_year"=1975, "poster_url"='https://image.tmdb.org/t/p/w500/7BAXwmFN4pZDNb9N6kzmAAwdssi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/41Mlaj6wfjlF4wQaVH0tjfDXvMi.jpg', "overview"='In the early 1900s, Miranda attends a girls boarding school in Australia. One Valentine''s Day, the school''s typically strict headmistress treats the girls to a picnic field trip to an unusual but scenic volcanic formation called Hanging Rock. Despite rules against it, Miranda and several other girls venture off. It''s not until the end of the day that the faculty realizes the girls and one of the teachers have disappeared mysteriously.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5711, "vote_average"=7.233, "is_ambiguous"=0, "evidence_score"=1.88413333333333348e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=17;
UPDATE "recommendations" SET "tmdb_id"=179111, "imdb_id"='tt2375574', "igdb_id"=NULL, "title"='A Field in England', "original_title"='A Field in England', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/dKhMJr8yoHVyvxyUiAeIn2hKVdL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/euBvKWkvYD38O7dMMvw3GvrkZoa.jpg', "overview"='During the Civil War in 17th-Century England, a small group of deserters flee from a raging battle through an overgrown field. They are captured by an alchemist, who forces the group to aid him in his search to find a hidden treasure that he believes is buried in the field. Crossing a vast mushroom circle, which provides their first meal, the group quickly descend into a chaos of arguments, fighting and paranoia, and, as it becomes clear that the treasure might be something other than gold, they slowly become victim to the terrifying energies trapped inside the field.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.193, "vote_average"=6.212, "is_ambiguous"=0, "evidence_score"=1.11985714285714283e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=21;
UPDATE "recommendations" SET "tmdb_id"=13597, "imdb_id"='tt0091369', "igdb_id"=NULL, "title"='Labyrinth', "original_title"='Labyrinth', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mGkleIuPO2flRyvP8yBcUykSQsp.jpg', "overview"='Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6038, "vote_average"=7.289, "is_ambiguous"=0, "evidence_score"=2.218333333333333e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=23;
UPDATE "recommendations" SET "tmdb_id"=546554, "imdb_id"='tt8946378', "igdb_id"=NULL, "title"='Knives Out', "original_title"='Knives Out', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4HWAQu28e2yaWrtupFPGFkdNU7V.jpg', "overview"='When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.1335, "vote_average"=7.84, "is_ambiguous"=0, "evidence_score"=12.833, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=25;
UPDATE "recommendations" SET "tmdb_id"=530385, "imdb_id"='tt8772262', "igdb_id"=NULL, "title"='Midsommar', "original_title"='Midsommar', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pYgj8e2Y6RufnSyOA6OnzmxFXxZ.jpg', "overview"='Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.9695, "vote_average"=7.148, "is_ambiguous"=0, "evidence_score"=2.2014705882352942e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=27;
