UPDATE "recommendations" SET "tmdb_id"=11236, "imdb_id"='tt0108071', "igdb_id"=NULL, "title"='The Secret Garden', "original_title"='The Secret Garden', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/zf6h5dJ7wVG7LqMO9dhHGHVejzj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8s7FJ9dHXgeFZdvxfjPmrrJh6EC.jpg', "overview"='A young British girl born and reared in India loses her neglectful parents in an earthquake. She is returned to England to live at her uncle''s castle. Her uncle is very distant due to the loss of his wife ten years before. Neglected once again, she begins exploring the estate and discovers a garden that has been locked and forgotten. Aided by one of the servants'' boys, she begins restoring the garden, and eventually discovers some other secrets of the manor.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4349, "vote_average"=7.425, "is_ambiguous"=0, "evidence_score"=1.83714285714285736e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=166;
