UPDATE "recommendations" SET "tmdb_id"=276907, "imdb_id"='tt3569230', "igdb_id"=NULL, "title"='Legend', "original_title"='Legend', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/4shf5Alq4KWCKqrAAQe0JGJHYp5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v8zOcynvSd6IW3FzZrvst2HJ53s.jpg', "overview"='Suave, charming and volatile, Reggie Kray and his unstable twin brother Ronnie start to leave their mark on the London underworld in the 1960s. Using violence to get what they want, the siblings orchestrate robberies and murders while running nightclubs and protection rackets. With police Detective Leonard "Nipper" Read hot on their heels, the brothers continue their rapid rise to power and achieve tabloid notoriety.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.8362, "vote_average"=7.05, "is_ambiguous"=0, "evidence_score"=6.54, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=744;
