UPDATE "recommendations" SET "tmdb_id"=15, "imdb_id"='tt0033467', "igdb_id"=NULL, "title"='Citizen Kane', "original_title"='Citizen Kane', "media_type"='movie', "release_year"=1941, "poster_url"='https://image.tmdb.org/t/p/w500/sav0jxhqiH0bPr2vZFU0Kjt2nZL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ruF3Lmd4A8MHbnEBE6lxPMbsHGL.jpg', "overview"='Newspaper magnate Charles Foster Kane is taken from his mother as a boy and made the ward of a rich industrialist. As a result, every well-meaning, tyrannical or self-destructive move he makes for the rest of his life appears in some way to be a reaction to that deeply wounding event.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.2754, "vote_average"=8.0, "is_ambiguous"=0, "evidence_score"=8.765, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=1102;
UPDATE "recommendations" SET "tmdb_id"=133121, "imdb_id"='tt1753496', "igdb_id"=NULL, "title"='Resident Evil: Damnation', "original_title"='バイオハザード ダムネーション', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/zkHSURVCrt7rpvDDgUXO75CV1v4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xbjOkrAaT4CAIrNJ38oQSBomHvg.jpg', "overview"='U.S. federal agent Leon S. Kennedy sneaks into the "East Slavic Republic" to verify rumors that Bio-Organic Weapons (BOWs) are being used in the country''s civil war, which the U.S. and Russia are making preparations to jointly intervene in. Right after his infiltration, the U.S. government orders him to leave immediately. Determined to uncover the truth, Leon ignores the order and enters the battlefield to end the chain of tragedies caused by the BOWs.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.6379, "vote_average"=6.896, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=1104;
