UPDATE "recommendations" SET "tmdb_id"=187, "imdb_id"='tt0401792', "igdb_id"=NULL, "title"='Sin City', "original_title"='Sin City', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/i66G50wATMmPrvpP95f0XP6ZdVS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/t9kQnqiaxQ8TLB25rTzDKLd0fdM.jpg', "overview"='Welcome to Sin City. This town beckons to the tough, the corrupt, the brokenhearted. Some call it dark… Hard-boiled. Then there are those who call it home — Crooked cops, sexy dames, desperate vigilantes. Some are seeking revenge, others lust after redemption, and then there are those hoping for a little of both. A universe of unlikely and reluctant heroes still trying to do the right thing in a city that refuses to care.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.0682, "vote_average"=7.465, "is_ambiguous"=0, "evidence_score"=1.73546153846153856e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=1134;
