UPDATE "recommendations" SET "tmdb_id"=11953, "imdb_id"='tt0080979', "igdb_id"=NULL, "title"='Kagemusha', "original_title"='影武者', "media_type"='movie', "release_year"=1980, "poster_url"='https://image.tmdb.org/t/p/w500/fJgqj9s8HNZz9zwX6femVJn8HEB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7qsKE8GsgjreeQ2mTLd5oKZ7Tbf.jpg', "overview"='Akira Kurosawa''s lauded feudal epic presents the tale of a petty thief who is recruited to impersonate Shingen, an aging warlord, in order to avoid attacks by competing clans. When Shingen dies, his generals reluctantly agree to have the impostor take over as the powerful ruler. He soon begins to appreciate life as Shingen, but his commitment to the role is tested when he must lead his troops into battle against the forces of a rival warlord.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.7673, "vote_average"=7.819, "is_ambiguous"=0, "evidence_score"=6.52999999999999936e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=1621;
