UPDATE "recommendations" SET "tmdb_id"=1648, "imdb_id"='tt0096928', "igdb_id"=NULL, "title"='Bill & Ted''s Excellent Adventure', "original_title"='Bill & Ted''s Excellent Adventure', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/tV25lGWGWGEqUe3U0xjQTBgilSx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aMASmAmkn7NT0nEq8PBZEgwBfGN.jpg', "overview"='Bill and Ted are high school buddies starting a band. They are also about to fail their history class—which means Ted would be sent to military school—but receive help from Rufus, a traveller from a future where their band is the foundation for a perfect society. With the use of Rufus'' time machine, Bill and Ted travel to various points in history, returning with important figures to help them complete their final history presentation.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.406, "vote_average"=6.844, "is_ambiguous"=0, "evidence_score"=1.52877777777777765e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=1848;
