UPDATE "recommendations" SET "tmdb_id"=840430, "imdb_id"='tt14849194', "igdb_id"=NULL, "title"='The Holdovers', "original_title"='The Holdovers', "media_type"='movie', "release_year"=2023, "poster_url"='https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/A99WMiz0ASpH9coOFrxSEuwTWx0.jpg', "overview"='A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.9543, "vote_average"=7.646, "is_ambiguous"=0, "evidence_score"=1.61500000000000021e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-03 14:31:56' WHERE "id"=2373;
